import { updateTag } from 'next/cache';

export async function createPost(formData: FormData) {
  // Extract data from the form (e.g., title, content)
  const title = formData.get('title') as string;
  const content = formData.get('content') as string;

  // Simulate creating a new post (e.g., saving to a database)
  console.log(`Creating post: ${title} - ${content}`);
  await new Promise((resolve) => setTimeout(resolve, 500)); // Mock delay

  // Invalidate the 'posts' cache tag using updateTag.
  // This function is specifically designed for Server Actions to enable 
  // read-your-own-writes semantics, guaranteeing the next page load waits 
  // for fresh data and does not serve stale cached content.
  updateTag('posts');
}
